/* ============================================================
   GlobalStone — Global Commercial Real Estate Services
   Brand Colors: #003F2D (forest green), #012A2D (dark teal)
   ============================================================ */

/* --- CSS Custom Properties --- */
:root {
  --color-primary: #003F2D;
  --color-primary-light: #00563D;
  --color-primary-dark: #002B1E;
  --color-secondary: #012A2D;
  --color-secondary-light: #024044;
  --color-accent: #C8A84E;
  --color-accent-hover: #B8993E;
  --color-white: #FFFFFF;
  --color-off-white: #F8F8F6;
  --color-gray-50: #F5F5F3;
  --color-gray-100: #E6E6E6;
  --color-gray-200: #D1D1CF;
  --color-gray-300: #A8A8A6;
  --color-gray-400: #7A7A78;
  --color-gray-500: #5C5C5A;
  --color-gray-600: #40403E;
  --color-gray-700: #2A2A28;
  --color-gray-800: #1A1A18;
  --color-gray-900: #0D0D0C;
  --color-navy: #0A1628;
  --color-navy-light: #122240;
  --font-heading: 'Playfair Display', Georgia, 'Times New Roman', serif;
  --font-body: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --font-mono: 'JetBrains Mono', 'Fira Code', monospace;
  --radius-sm: 0.375rem;
  --radius-md: 0.5rem;
  --radius-lg: 0.75rem;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.06);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
  --shadow-lg: 0 12px 40px rgba(0,0,0,0.12);
  --shadow-xl: 0 20px 60px rgba(0,0,0,0.15);
  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 400ms ease;
  --max-width: 1200px;
  --header-height: 72px;
}

/* --- Reset & Base --- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
  color: var(--color-gray-800);
  background: var(--color-white);
  overflow-x: hidden;
}

img { max-width: 100%; height: auto; display: block; }
a { color: inherit; text-decoration: none; }
button { cursor: pointer; font-family: inherit; border: none; background: none; }
ul, ol { list-style: none; }

/* --- Typography --- */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 700;
  line-height: 1.2;
  color: var(--color-navy);
}

h1 { font-size: clamp(2.25rem, 5vw, 3.75rem); }
h2 { font-size: clamp(1.75rem, 4vw, 2.75rem); }
h3 { font-size: clamp(1.25rem, 3vw, 1.75rem); }
h4 { font-size: 1.25rem; }

.text-eyebrow {
  font-family: var(--font-body);
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--color-primary);
}

.text-body-lg { font-size: 1.125rem; line-height: 1.75; color: var(--color-gray-600); }
.text-body { font-size: 1rem; line-height: 1.7; color: var(--color-gray-600); }
.text-caption { font-size: 0.875rem; color: var(--color-gray-400); }

/* --- Container --- */
.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 1.5rem;
}

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.75rem 1.75rem;
  font-family: var(--font-body);
  font-size: 0.9375rem;
  font-weight: 600;
  border-radius: var(--radius-sm);
  transition: all var(--transition-fast);
  white-space: nowrap;
}

.btn-primary {
  background: var(--color-primary);
  color: var(--color-white);
  border: 2px solid var(--color-primary);
}
.btn-primary:hover {
  background: var(--color-primary-light);
  border-color: var(--color-primary-light);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-accent {
  background: var(--color-accent);
  color: var(--color-navy);
  border: 2px solid var(--color-accent);
}
.btn-accent:hover {
  background: var(--color-accent-hover);
  border-color: var(--color-accent-hover);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-outline {
  background: transparent;
  color: var(--color-primary);
  border: 2px solid var(--color-primary);
}
.btn-outline:hover {
  background: var(--color-primary);
  color: var(--color-white);
}

.btn-outline-light {
  background: transparent;
  color: var(--color-white);
  border: 2px solid rgba(255,255,255,0.6);
}
.btn-outline-light:hover {
  background: var(--color-white);
  color: var(--color-navy);
  border-color: var(--color-white);
}

.btn-link {
  padding: 0;
  color: var(--color-primary);
  font-weight: 600;
  border-bottom: 2px solid transparent;
  border-radius: 0;
}
.btn-link:hover { border-bottom-color: var(--color-primary); }
.btn-link::after {
  content: ' →';
  transition: transform var(--transition-fast);
  display: inline-block;
}
.btn-link:hover::after { transform: translateX(4px); }

.btn-link-light {
  padding: 0;
  color: var(--color-white);
  font-weight: 600;
  border-bottom: 2px solid transparent;
  border-radius: 0;
}
.btn-link-light:hover { border-bottom-color: var(--color-white); }
.btn-link-light::after {
  content: ' →';
  transition: transform var(--transition-fast);
  display: inline-block;
}
.btn-link-light:hover::after { transform: translateX(4px); }

/* ============================================================
   HEADER & NAVIGATION
   ============================================================ */
.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: var(--header-height);
  background: var(--color-white);
  border-bottom: 1px solid var(--color-gray-100);
  z-index: 1000;
  transition: box-shadow var(--transition-base);
}
.header.scrolled { box-shadow: var(--shadow-md); }

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 1.5rem;
}

.header-logo {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--color-primary);
  flex-shrink: 0;
}

.header-logo-icon {
  width: 36px;
  height: 36px;
  background: var(--color-primary);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-white);
  font-size: 1.25rem;
  font-weight: 700;
}

/* --- Desktop Nav --- */
.nav-desktop { display: flex; align-items: center; gap: 0.25rem; }

.nav-link {
  padding: 0.5rem 0.875rem;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--color-gray-700);
  border-radius: var(--radius-sm);
  transition: all var(--transition-fast);
  position: relative;
  white-space: nowrap;
}
.nav-link:hover, .nav-link.active {
  color: var(--color-primary);
  background: var(--color-gray-50);
}
.nav-link.active::after {
  content: '';
  position: absolute;
  bottom: -1px;
  left: 0.875rem;
  right: 0.875rem;
  height: 2px;
  background: var(--color-primary);
}

.nav-link-services {
  display: flex;
  align-items: center;
  gap: 0.25rem;
}

.nav-chevron {
  width: 16px;
  height: 16px;
  transition: transform var(--transition-fast);
}
.nav-link-services.open .nav-chevron { transform: rotate(180deg); }

.nav-cta {
  margin-left: 0.75rem;
  padding: 0.5rem 1.25rem;
  font-size: 0.8125rem;
  font-weight: 600;
  background: var(--color-primary);
  color: var(--color-white);
  border-radius: var(--radius-sm);
  transition: all var(--transition-fast);
}
.nav-cta:hover {
  background: var(--color-primary-light);
  transform: translateY(-1px);
  box-shadow: var(--shadow-sm);
}

/* --- Mega Menu --- */
.mega-menu {
  position: fixed;
  top: var(--header-height);
  left: 0;
  right: 0;
  background: var(--color-white);
  border-top: 1px solid var(--color-gray-100);
  box-shadow: var(--shadow-xl);
  opacity: 0;
  visibility: hidden;
  transform: translateY(-8px);
  transition: all var(--transition-base);
  z-index: 999;
}
.mega-menu.open {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

.mega-menu-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 2.5rem 1.5rem;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
}

.mega-menu-col h4 {
  font-family: var(--font-body);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--color-gray-400);
  margin-bottom: 1.25rem;
  padding-bottom: 0.75rem;
  border-bottom: 1px solid var(--color-gray-100);
}

.mega-menu-list { display: flex; flex-direction: column; gap: 0.25rem; }

.mega-menu-link {
  display: block;
  padding: 0.625rem 0.75rem;
  font-size: 0.9375rem;
  color: var(--color-gray-700);
  border-radius: var(--radius-sm);
  transition: all var(--transition-fast);
}
.mega-menu-link:hover {
  color: var(--color-primary);
  background: var(--color-gray-50);
  padding-left: 1rem;
}

/* --- Mega Menu Overlay --- */
.mega-overlay {
  position: fixed;
  inset: 0;
  top: var(--header-height);
  background: rgba(0,0,0,0.3);
  opacity: 0;
  visibility: hidden;
  transition: all var(--transition-base);
  z-index: 998;
}
.mega-overlay.open { opacity: 1; visibility: visible; }

/* --- Mobile Nav --- */
.nav-mobile-toggle {
  display: none;
  width: 44px;
  height: 44px;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.nav-mobile-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--color-gray-800);
  position: relative;
  transition: all var(--transition-fast);
}
.nav-mobile-toggle span::before,
.nav-mobile-toggle span::after {
  content: '';
  position: absolute;
  left: 0;
  width: 100%;
  height: 2px;
  background: var(--color-gray-800);
  transition: all var(--transition-fast);
}
.nav-mobile-toggle span::before { top: -8px; }
.nav-mobile-toggle span::after { top: 8px; }

.nav-mobile-toggle.open span { background: transparent; }
.nav-mobile-toggle.open span::before { top: 0; transform: rotate(45deg); }
.nav-mobile-toggle.open span::after { top: 0; transform: rotate(-45deg); }

.mobile-nav {
  display: none;
  position: fixed;
  top: var(--header-height);
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--color-white);
  overflow-y: auto;
  z-index: 1001;
  transform: translateX(100%);
  transition: transform var(--transition-base);
}
.mobile-nav.open { transform: translateX(0); }

.mobile-nav-inner { padding: 1rem 1.5rem 3rem; }

.mobile-nav-item {
  border-bottom: 1px solid var(--color-gray-100);
}

.mobile-nav-link {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1rem 0;
  font-size: 1rem;
  font-weight: 500;
  color: var(--color-gray-800);
}

.mobile-nav-accordion-btn {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 1rem 0;
  font-size: 1rem;
  font-weight: 500;
  color: var(--color-gray-800);
  text-align: left;
}

.mobile-accordion-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-base);
  background: var(--color-gray-50);
  border-radius: var(--radius-sm);
  margin-bottom: 0.5rem;
}
.mobile-accordion-content.open { max-height: 500px; }

.mobile-sub-label {
  display: block;
  padding: 0.5rem 1rem 0.25rem;
  font-size: 0.6875rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--color-gray-400);
}

.mobile-sub-link {
  display: block;
  padding: 0.625rem 1rem;
  font-size: 0.9375rem;
  color: var(--color-gray-700);
  transition: color var(--transition-fast);
}
.mobile-sub-link:hover { color: var(--color-primary); }

/* ============================================================
   HERO SECTIONS
   ============================================================ */
.hero {
  position: relative;
  min-height: 85vh;
  display: flex;
  align-items: center;
  background: var(--color-navy);
  margin-top: var(--header-height);
  overflow: hidden;
}

.hero-bg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  opacity: 0.55;
}

.hero-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    135deg,
    rgba(0,39,28,0.85) 0%,
    rgba(1,42,45,0.7) 50%,
    rgba(10,22,40,0.6) 100%
  );
}

.hero-content {
  position: relative;
  z-index: 2;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 4rem 1.5rem;
  width: 100%;
}

.hero-label {
  display: inline-block;
  padding: 0.375rem 0.875rem;
  background: rgba(255,255,255,0.15);
  backdrop-filter: blur(8px);
  border: 1px solid rgba(255,255,255,0.2);
  border-radius: 9999px;
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--color-white);
  margin-bottom: 1.5rem;
}

.hero h1 {
  color: var(--color-white);
  max-width: 750px;
  margin-bottom: 1.5rem;
}

.hero-subtitle {
  font-size: 1.125rem;
  line-height: 1.7;
  color: rgba(255,255,255,0.85);
  max-width: 600px;
  margin-bottom: 2rem;
}

.hero-actions { display: flex; gap: 1rem; flex-wrap: wrap; }

/* Hero variants */
.hero-sm { min-height: 50vh; }
.hero-sm .hero-content { padding: 3rem 1.5rem; }
.hero-sm h1 { max-width: 650px; }

/* ============================================================
   SECTIONS
   ============================================================ */
.section {
  padding: 5rem 0;
}

.section-header {
  text-align: center;
  margin-bottom: 3.5rem;
}

.section-header h2 { margin-bottom: 0.75rem; }
.section-header p {
  max-width: 600px;
  margin: 0 auto;
  color: var(--color-gray-500);
  font-size: 1.0625rem;
}

.section-dark {
  background: var(--color-navy);
  color: var(--color-white);
}
.section-dark h2, .section-dark h3 { color: var(--color-white); }
.section-dark p { color: rgba(255,255,255,0.75); }

.section-light { background: var(--color-gray-50); }

/* ============================================================
   CARDS
   ============================================================ */
.card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(340px, 1fr));
  gap: 1.5rem;
}

.card-grid-3 { grid-template-columns: repeat(3, 1fr); }
.card-grid-4 { grid-template-columns: repeat(4, 1fr); }

.card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-100);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: all var(--transition-base);
}
.card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
  border-color: transparent;
}

.card-image {
  width: 100%;
  height: 200px;
  object-fit: cover;
}

.card-body { padding: 1.5rem; }

.card-tag {
  display: inline-block;
  padding: 0.25rem 0.625rem;
  background: var(--color-gray-50);
  border-radius: 9999px;
  font-size: 0.6875rem;
  font-weight: 600;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--color-primary);
  margin-bottom: 0.75rem;
}

.card h3 { font-size: 1.125rem; margin-bottom: 0.5rem; }
.card p { font-size: 0.9375rem; color: var(--color-gray-500); margin-bottom: 1rem; }

.card-footer {
  padding: 1rem 1.5rem;
  border-top: 1px solid var(--color-gray-100);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.card-date {
  font-size: 0.8125rem;
  color: var(--color-gray-400);
}

/* Service Cards */
.service-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-100);
  border-radius: var(--radius-lg);
  padding: 2rem;
  transition: all var(--transition-base);
  display: flex;
  flex-direction: column;
}
.service-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
  border-color: transparent;
}

.service-card-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-md);
  background: var(--color-gray-50);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.25rem;
  font-size: 1.5rem;
  color: var(--color-primary);
  transition: all var(--transition-base);
}
.service-card:hover .service-card-icon {
  background: var(--color-primary);
  color: var(--color-white);
}

.service-card h3 { margin-bottom: 0.5rem; }
.service-card p {
  color: var(--color-gray-500);
  font-size: 0.9375rem;
  flex: 1;
  margin-bottom: 1.25rem;
}

/* Insight Cards */
.insight-card {
  display: flex;
  gap: 1.25rem;
  padding: 1.5rem;
  background: var(--color-white);
  border: 1px solid var(--color-gray-100);
  border-radius: var(--radius-lg);
  transition: all var(--transition-base);
}
.insight-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.insight-card-thumb {
  width: 100px;
  height: 100px;
  border-radius: var(--radius-md);
  object-fit: cover;
  flex-shrink: 0;
}

.insight-card-content h4 {
  font-size: 1rem;
  font-family: var(--font-heading);
  margin-bottom: 0.375rem;
}
.insight-card-content .card-tag { margin-bottom: 0.5rem; }

/* Commitment Cards */
.commitment-card {
  background: var(--color-navy-light);
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: var(--radius-lg);
  padding: 2rem;
  transition: all var(--transition-base);
}
.commitment-card:hover {
  transform: translateY(-4px);
  border-color: rgba(255,255,255,0.2);
  background: rgba(255,255,255,0.05);
}

.commitment-card-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-md);
  background: rgba(200,168,78,0.15);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.25rem;
  color: var(--color-accent);
  font-size: 1.375rem;
}

.commitment-card h3 {
  color: var(--color-white);
  font-size: 1.25rem;
  margin-bottom: 0.625rem;
}
.commitment-card p {
  color: rgba(255,255,255,0.65);
  font-size: 0.9375rem;
  margin-bottom: 1.25rem;
  line-height: 1.7;
}

/* Capability card */
.capability-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-100);
  border-left: 3px solid var(--color-primary);
  border-radius: 0 var(--radius-md) var(--radius-md) 0;
  padding: 1.75rem;
  transition: all var(--transition-base);
}
.capability-card:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-md);
  border-left-color: var(--color-accent);
}

.capability-card h4 {
  font-family: var(--font-heading);
  font-size: 1.125rem;
  margin-bottom: 0.5rem;
  color: var(--color-navy);
}
.capability-card p {
  font-size: 0.9375rem;
  color: var(--color-gray-500);
  line-height: 1.65;
}

/* ============================================================
   ANNOUNCEMENT BANNER
   ============================================================ */
.announcement-banner {
  background: linear-gradient(135deg, var(--color-secondary) 0%, var(--color-secondary-light) 100%);
  padding: 2rem 0;
}

.announcement-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.5rem;
  flex-wrap: wrap;
}

.announcement-text {
  color: var(--color-white);
  font-size: 1.0625rem;
  font-weight: 500;
}

.announcement-dot {
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--color-accent);
  margin-right: 0.75rem;
  animation: pulse-dot 2s ease-in-out infinite;
}

@keyframes pulse-dot {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.5; transform: scale(1.3); }
}

/* ============================================================
   WHAT WE DO — TABBED SECTION
   ============================================================ */
.what-we-do {
  display: grid;
  grid-template-columns: 320px 1fr;
  gap: 3rem;
  align-items: start;
}

.tabs-vertical { display: flex; flex-direction: column; gap: 0.25rem; }

.tab-btn {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 1.125rem 1.25rem;
  text-align: left;
  font-size: 1rem;
  font-weight: 500;
  color: var(--color-gray-600);
  border-left: 3px solid transparent;
  border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
  transition: all var(--transition-fast);
  background: transparent;
}
.tab-btn:hover {
  color: var(--color-primary);
  background: var(--color-gray-50);
}

.tab-btn.active {
  color: var(--color-primary);
  background: var(--color-gray-50);
  border-left-color: var(--color-primary);
  font-weight: 600;
}

.tab-arrow {
  opacity: 0;
  transform: translateX(-8px);
  transition: all var(--transition-fast);
}
.tab-btn.active .tab-arrow { opacity: 1; transform: translateX(0); }

.tab-panel { display: none; }
.tab-panel.active { display: block; }
.tab-panel-inner { animation: fadeSlideIn 400ms ease-out; }

@keyframes fadeSlideIn {
  from { opacity: 0; transform: translateY(12px); }
  to { opacity: 1; transform: translateY(0); }
}

.tab-panel h3 {
  font-size: 1.75rem;
  margin-bottom: 0.75rem;
}

.tab-panel p {
  font-size: 1.0625rem;
  color: var(--color-gray-500);
  line-height: 1.75;
  margin-bottom: 1.5rem;
  max-width: 540px;
}

/* ============================================================
   NEWSLETTER
   ============================================================ */
.newsletter {
  background: var(--color-gray-50);
  padding: 4rem 0;
}

.newsletter-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-100);
  border-radius: var(--radius-lg);
  padding: 3rem;
  text-align: center;
  max-width: 640px;
  margin: 0 auto;
  box-shadow: var(--shadow-sm);
}

.newsletter-card h2 { margin-bottom: 0.5rem; }
.newsletter-card .text-body { margin-bottom: 1.75rem; }

.newsletter-form {
  display: flex;
  gap: 0.75rem;
  max-width: 460px;
  margin: 0 auto;
}

.newsletter-input {
  flex: 1;
  padding: 0.75rem 1rem;
  font-family: var(--font-body);
  font-size: 0.9375rem;
  border: 2px solid var(--color-gray-200);
  border-radius: var(--radius-sm);
  transition: border-color var(--transition-fast);
  outline: none;
}
.newsletter-input:focus { border-color: var(--color-primary); }

/* ============================================================
   PARTNER CAROUSEL (Invest page)
   ============================================================ */
.carousel {
  position: relative;
  overflow: hidden;
}

.carousel-track {
  display: flex;
  transition: transform var(--transition-slow);
}

.carousel-slide {
  min-width: 100%;
  padding: 0 0.5rem;
}

.carousel-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  margin-top: 2rem;
}

.carousel-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 2px solid var(--color-gray-200);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-gray-600);
  transition: all var(--transition-fast);
}
.carousel-btn:hover {
  border-color: var(--color-primary);
  color: var(--color-primary);
  background: var(--color-gray-50);
}

.carousel-dots { display: flex; gap: 0.5rem; }

.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--color-gray-200);
  transition: all var(--transition-fast);
}
.carousel-dot.active {
  background: var(--color-primary);
  width: 28px;
  border-radius: 9999px;
}

/* ============================================================
   TESTIMONIAL
   ============================================================ */
.testimonial {
  padding: 3.5rem 0;
  background: var(--color-gray-50);
}

.testimonial-card {
  max-width: 750px;
  margin: 0 auto;
  text-align: center;
}

.testimonial-quote {
  font-family: var(--font-heading);
  font-size: clamp(1.25rem, 3vw, 1.5rem);
  font-style: italic;
  color: var(--color-navy);
  line-height: 1.6;
  margin-bottom: 1.5rem;
  position: relative;
}
.testimonial-quote::before {
  content: '"';
  font-size: 4rem;
  color: var(--color-accent);
  position: absolute;
  top: -1.5rem;
  left: -1rem;
  font-family: var(--font-heading);
  line-height: 1;
  opacity: 0.4;
}

.testimonial-author {
  font-weight: 600;
  color: var(--color-gray-800);
}
.testimonial-role {
  font-size: 0.875rem;
  color: var(--color-gray-400);
}

/* ============================================================
   FEATURED TOPICS (sidebar)
   ============================================================ */
.featured-topics {
  background: var(--color-gray-50);
  border-radius: var(--radius-lg);
  padding: 1.75rem;
}

.featured-topics h4 {
  font-family: var(--font-body);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--color-gray-400);
  margin-bottom: 1rem;
}

.topic-link {
  display: block;
  padding: 0.75rem 0;
  border-bottom: 1px solid var(--color-gray-100);
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--color-gray-700);
  transition: all var(--transition-fast);
}
.topic-link:last-child { border-bottom: none; }
.topic-link:hover { color: var(--color-primary); padding-left: 0.5rem; }

/* ============================================================
   PAGE HEADER & BREADCRUMB
   ============================================================ */
.page-hero {
  position: relative;
  min-height: 35vh;
  display: flex;
  align-items: center;
  background: var(--color-navy);
  margin-top: var(--header-height);
  overflow: hidden;
}

.page-hero-bg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  opacity: 0.45;
}

.page-hero-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, rgba(0,39,28,0.88) 0%, rgba(1,42,45,0.72) 100%);
}

.page-hero-content {
  position: relative;
  z-index: 2;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 3rem 1.5rem;
  width: 100%;
}

.breadcrumb {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-bottom: 1rem;
  font-size: 0.875rem;
  color: rgba(255,255,255,0.7);
}
.breadcrumb a { color: rgba(255,255,255,0.9); }
.breadcrumb a:hover { color: var(--color-white); text-decoration: underline; }
.breadcrumb-sep { color: rgba(255,255,255,0.4); }

.page-hero-content h1 {
  color: var(--color-white);
  max-width: 650px;
}

/* ============================================================
   STAT BAND
   ============================================================ */
.stat-band {
  padding: 3rem 0;
  background: var(--color-primary);
}

.stat-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
  text-align: center;
}

.stat-number {
  font-family: var(--font-heading);
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--color-accent);
  margin-bottom: 0.25rem;
}

.stat-label {
  font-size: 0.9375rem;
  color: rgba(255,255,255,0.8);
}

/* ============================================================
   PARTNERSHIP HIGHLIGHT
   ============================================================ */
.partner-highlight {
  background: linear-gradient(135deg, var(--color-secondary) 0%, var(--color-navy) 100%);
  padding: 3.5rem 0;
  color: var(--color-white);
}

.partner-highlight-inner {
  max-width: 750px;
  margin: 0 auto;
  text-align: center;
}

.partner-highlight h2 { color: var(--color-white); margin-bottom: 1rem; }
.partner-highlight p {
  color: rgba(255,255,255,0.8);
  font-size: 1.0625rem;
  line-height: 1.75;
}

.partner-stats {
  display: flex;
  justify-content: center;
  gap: 3rem;
  margin-top: 2rem;
}

.partner-stat {
  text-align: center;
}
.partner-stat-number {
  font-family: var(--font-heading);
  font-size: 2.25rem;
  font-weight: 700;
  color: var(--color-accent);
}
.partner-stat-label {
  font-size: 0.875rem;
  color: rgba(255,255,255,0.7);
  margin-top: 0.25rem;
}

/* ============================================================
   RELATED CONTENT
   ============================================================ */
.related-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
}

.related-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-100);
  border-radius: var(--radius-lg);
  padding: 1.5rem;
  transition: all var(--transition-base);
}
.related-card:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-md);
}

.related-card .card-tag { margin-bottom: 0.75rem; }
.related-card h4 {
  font-family: var(--font-heading);
  font-size: 1rem;
  margin-bottom: 0.5rem;
}

/* ============================================================
   DEAL FLOW CTA
   ============================================================ */
.deal-flow-cta {
  background: var(--color-gray-50);
  border: 1px solid var(--color-gray-100);
  border-radius: var(--radius-lg);
  padding: 2.5rem;
  text-align: center;
}

.deal-flow-cta h3 { margin-bottom: 0.75rem; }
.deal-flow-cta p {
  max-width: 500px;
  margin: 0 auto 1.5rem;
  color: var(--color-gray-500);
}

/* ============================================================
   FOOTER
   ============================================================ */
.footer {
  background: var(--color-gray-900);
  color: var(--color-white);
  padding: 4rem 0 0;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 3rem;
  padding-bottom: 3rem;
  border-bottom: 1px solid rgba(255,255,255,0.1);
}

.footer-col h4 {
  font-family: var(--font-body);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: rgba(255,255,255,0.4);
  margin-bottom: 1.25rem;
}

.footer-col p {
  color: rgba(255,255,255,0.55);
  font-size: 0.9375rem;
  line-height: 1.7;
  max-width: 280px;
}

.footer-links { display: flex; flex-direction: column; gap: 0.5rem; }

.footer-links a {
  font-size: 0.9375rem;
  color: rgba(255,255,255,0.55);
  transition: color var(--transition-fast);
}
.footer-links a:hover { color: var(--color-white); }

.footer-bottom {
  padding: 1.5rem 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 1rem;
}

.footer-copyright {
  font-size: 0.8125rem;
  color: rgba(255,255,255,0.35);
}

.footer-legal { display: flex; gap: 1.5rem; flex-wrap: wrap; }
.footer-legal a {
  font-size: 0.8125rem;
  color: rgba(255,255,255,0.4);
  transition: color var(--transition-fast);
}
.footer-legal a:hover { color: rgba(255,255,255,0.7); }

/* ============================================================
   MODAL
   ============================================================ */
.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.6);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 2000;
  opacity: 0;
  visibility: hidden;
  transition: all var(--transition-base);
}
.modal-overlay.open { opacity: 1; visibility: visible; }

.modal {
  background: var(--color-white);
  border-radius: var(--radius-lg);
  padding: 2.5rem;
  max-width: 480px;
  width: 90%;
  box-shadow: var(--shadow-xl);
  text-align: center;
  transform: translateY(20px);
  transition: transform var(--transition-base);
}
.modal-overlay.open .modal { transform: translateY(0); }

.modal-close {
  position: absolute;
  top: 1rem;
  right: 1rem;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  color: var(--color-gray-400);
  transition: all var(--transition-fast);
}
.modal-close:hover { background: var(--color-gray-50); color: var(--color-gray-800); }

.modal h3 { margin-bottom: 0.5rem; }
.modal p { color: var(--color-gray-500); margin-bottom: 1.5rem; font-size: 0.9375rem; }

.modal .newsletter-form { max-width: 100%; }

.modal-success {
  display: none;
  padding: 1.5rem;
}
.modal-success.show { display: block; }
.modal-success-icon {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--color-primary);
  color: var(--color-white);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.75rem;
  margin: 0 auto 1rem;
}

/* ============================================================
   RESPONSIVE
   ============================================================ */
@media (max-width: 1024px) {
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .card-grid-3 { grid-template-columns: repeat(2, 1fr); }
  .card-grid-4 { grid-template-columns: repeat(2, 1fr); }
  .related-grid { grid-template-columns: repeat(2, 1fr); }
  .what-we-do { grid-template-columns: 250px 1fr; gap: 2rem; }
  .mega-menu-inner { gap: 2rem; }
}

@media (max-width: 768px) {
  .nav-desktop { display: none; }
  .nav-mobile-toggle { display: flex; }
  .mobile-nav { display: block; }

  .section { padding: 3rem 0; }
  .hero { min-height: 70vh; }
  .hero h1 { font-size: 2rem; }

  .what-we-do { grid-template-columns: 1fr; gap: 1.5rem; }
  .tabs-vertical {
    flex-direction: row;
    overflow-x: auto;
    gap: 0.25rem;
    padding-bottom: 0.5rem;
  }
  .tab-btn {
    border-left: none;
    border-bottom: 3px solid transparent;
    border-radius: var(--radius-sm) var(--radius-sm) 0 0;
    padding: 0.75rem 1rem;
    white-space: nowrap;
    flex-shrink: 0;
    font-size: 0.875rem;
  }
  .tab-btn.active {
    border-left-color: transparent;
    border-bottom-color: var(--color-primary);
  }
  .tab-arrow { display: none; }

  .mega-menu-inner { grid-template-columns: 1fr; gap: 1.5rem; }
  .card-grid { grid-template-columns: 1fr; }
  .card-grid-3 { grid-template-columns: 1fr; }
  .card-grid-4 { grid-template-columns: 1fr; }
  .related-grid { grid-template-columns: 1fr; }
  .stat-grid { grid-template-columns: 1fr; gap: 1.5rem; }
  .footer-grid { grid-template-columns: 1fr; gap: 2rem; }
  .partner-stats { flex-direction: column; gap: 1.5rem; }
  .insight-card { flex-direction: column; }
  .insight-card-thumb { width: 100%; height: 160px; }
  .announcement-inner { flex-direction: column; text-align: center; }
  .newsletter-form { flex-direction: column; }
  .newsletter-card { padding: 2rem 1.5rem; }
  .hero-actions { flex-direction: column; }
}

@media (max-width: 480px) {
  .container { padding: 0 1rem; }
  .section-header h2 { font-size: 1.5rem; }
  .btn { padding: 0.625rem 1.25rem; font-size: 0.875rem; }
}

/* ============================================================
   GlobalStone — Global Commercial Real Estate Services
   Brand Colors: #003F2D (forest green), #012A2D (dark teal)
   ============================================================ */

/* --- CSS Custom Properties --- */
:root {
  --color-primary: #003F2D;
  --color-primary-light: #00563D;
  --color-primary-dark: #002B1E;
  --color-secondary: #012A2D;
  --color-secondary-light: #024044;
  --color-accent: #C8A84E;
  --color-accent-hover: #B8993E;
  --color-white: #FFFFFF;
  --color-off-white: #F8F8F6;
  --color-gray-50: #F5F5F3;
  --color-gray-100: #E6E6E6;
  --color-gray-200: #D1D1CF;
  --color-gray-300: #A8A8A6;
  --color-gray-400: #7A7A78;
  --color-gray-500: #5C5C5A;
  --color-gray-600: #40403E;
  --color-gray-700: #2A2A28;
  --color-gray-800: #1A1A18;
  --color-gray-900: #0D0D0C;
  --color-navy: #0A1628;
  --color-navy-light: #122240;
  --font-heading: 'Playfair Display', Georgia, 'Times New Roman', serif;
  --font-body: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --font-mono: 'JetBrains Mono', 'Fira Code', monospace;
  --radius-sm: 0.375rem;
  --radius-md: 0.5rem;
  --radius-lg: 0.75rem;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.06);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
  --shadow-lg: 0 12px 40px rgba(0,0,0,0.12);
  --shadow-xl: 0 20px 60px rgba(0,0,0,0.15);
  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 400ms ease;
  --max-width: 1200px;
  --header-height: 72px;
}

/* --- Reset & Base --- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
  color: var(--color-gray-800);
  background: var(--color-white);
  overflow-x: hidden;
}

img { max-width: 100%; height: auto; display: block; }
a { color: inherit; text-decoration: none; }
button { cursor: pointer; font-family: inherit; border: none; background: none; }
ul, ol { list-style: none; }

/* --- Typography --- */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 700;
  line-height: 1.2;
  color: var(--color-navy);
}

h1 { font-size: clamp(2.25rem, 5vw, 3.75rem); }
h2 { font-size: clamp(1.75rem, 4vw, 2.75rem); }
h3 { font-size: clamp(1.25rem, 3vw, 1.75rem); }
h4 { font-size: 1.25rem; }

.text-eyebrow {
  font-family: var(--font-body);
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--color-primary);
}

.text-body-lg { font-size: 1.125rem; line-height: 1.75; color: var(--color-gray-600); }
.text-body { font-size: 1rem; line-height: 1.7; color: var(--color-gray-600); }
.text-caption { font-size: 0.875rem; color: var(--color-gray-400); }

/* --- Container --- */
.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 1.5rem;
}

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.75rem 1.75rem;
  font-family: var(--font-body);
  font-size: 0.9375rem;
  font-weight: 600;
  border-radius: var(--radius-sm);
  transition: all var(--transition-fast);
  white-space: nowrap;
}

.btn-primary {
  background: var(--color-primary);
  color: var(--color-white);
  border: 2px solid var(--color-primary);
}
.btn-primary:hover {
  background: var(--color-primary-light);
  border-color: var(--color-primary-light);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-accent {
  background: var(--color-accent);
  color: var(--color-navy);
  border: 2px solid var(--color-accent);
}
.btn-accent:hover {
  background: var(--color-accent-hover);
  border-color: var(--color-accent-hover);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-outline {
  background: transparent;
  color: var(--color-primary);
  border: 2px solid var(--color-primary);
}
.btn-outline:hover {
  background: var(--color-primary);
  color: var(--color-white);
}

.btn-outline-light {
  background: transparent;
  color: var(--color-white);
  border: 2px solid rgba(255,255,255,0.6);
}
.btn-outline-light:hover {
  background: var(--color-white);
  color: var(--color-navy);
  border-color: var(--color-white);
}

.btn-link {
  padding: 0;
  color: var(--color-primary);
  font-weight: 600;
  border-bottom: 2px solid transparent;
  border-radius: 0;
}
.btn-link:hover { border-bottom-color: var(--color-primary); }
.btn-link::after {
  content: ' →';
  transition: transform var(--transition-fast);
  display: inline-block;
}
.btn-link:hover::after { transform: translateX(4px); }

.btn-link-light {
  padding: 0;
  color: var(--color-white);
  font-weight: 600;
  border-bottom: 2px solid transparent;
  border-radius: 0;
}
.btn-link-light:hover { border-bottom-color: var(--color-white); }
.btn-link-light::after {
  content: ' →';
  transition: transform var(--transition-fast);
  display: inline-block;
}
.btn-link-light:hover::after { transform: translateX(4px); }

/* ============================================================
   HEADER & NAVIGATION
   ============================================================ */
.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: var(--header-height);
  background: var(--color-white);
  border-bottom: 1px solid var(--color-gray-100);
  z-index: 1000;
  transition: box-shadow var(--transition-base);
}
.header.scrolled { box-shadow: var(--shadow-md); }

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 1.5rem;
}

.header-logo {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--color-primary);
  flex-shrink: 0;
}

.header-logo-icon {
  width: 36px;
  height: 36px;
  background: var(--color-primary);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-white);
  font-size: 1.25rem;
  font-weight: 700;
}

/* --- Desktop Nav --- */
.nav-desktop { display: flex; align-items: center; gap: 0.25rem; }

.nav-link {
  padding: 0.5rem 0.875rem;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--color-gray-700);
  border-radius: var(--radius-sm);
  transition: all var(--transition-fast);
  position: relative;
  white-space: nowrap;
}
.nav-link:hover, .nav-link.active {
  color: var(--color-primary);
  background: var(--color-gray-50);
}
.nav-link.active::after {
  content: '';
  position: absolute;
  bottom: -1px;
  left: 0.875rem;
  right: 0.875rem;
  height: 2px;
  background: var(--color-primary);
}

.nav-link-services {
  display: flex;
  align-items: center;
  gap: 0.25rem;
}

.nav-chevron {
  width: 16px;
  height: 16px;
  transition: transform var(--transition-fast);
}
.nav-link-services.open .nav-chevron { transform: rotate(180deg); }

.nav-cta {
  margin-left: 0.75rem;
  padding: 0.5rem 1.25rem;
  font-size: 0.8125rem;
  font-weight: 600;
  background: var(--color-primary);
  color: var(--color-white);
  border-radius: var(--radius-sm);
  transition: all var(--transition-fast);
}
.nav-cta:hover {
  background: var(--color-primary-light);
  transform: translateY(-1px);
  box-shadow: var(--shadow-sm);
}

/* --- Mega Menu --- */
.mega-menu {
  position: fixed;
  top: var(--header-height);
  left: 0;
  right: 0;
  background: var(--color-white);
  border-top: 1px solid var(--color-gray-100);
  box-shadow: var(--shadow-xl);
  opacity: 0;
  visibility: hidden;
  transform: translateY(-8px);
  transition: all var(--transition-base);
  z-index: 999;
}
.mega-menu.open {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

.mega-menu-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 2.5rem 1.5rem;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
}

.mega-menu-col h4 {
  font-family: var(--font-body);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--color-gray-400);
  margin-bottom: 1.25rem;
  padding-bottom: 0.75rem;
  border-bottom: 1px solid var(--color-gray-100);
}

.mega-menu-list { display: flex; flex-direction: column; gap: 0.25rem; }

.mega-menu-link {
  display: block;
  padding: 0.625rem 0.75rem;
  font-size: 0.9375rem;
  color: var(--color-gray-700);
  border-radius: var(--radius-sm);
  transition: all var(--transition-fast);
}
.mega-menu-link:hover {
  color: var(--color-primary);
  background: var(--color-gray-50);
  padding-left: 1rem;
}

/* --- Mega Menu Overlay --- */
.mega-overlay {
  position: fixed;
  inset: 0;
  top: var(--header-height);
  background: rgba(0,0,0,0.3);
  opacity: 0;
  visibility: hidden;
  transition: all var(--transition-base);
  z-index: 998;
}
.mega-overlay.open { opacity: 1; visibility: visible; }

/* --- Mobile Nav --- */
.nav-mobile-toggle {
  display: none;
  width: 44px;
  height: 44px;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.nav-mobile-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--color-gray-800);
  position: relative;
  transition: all var(--transition-fast);
}
.nav-mobile-toggle span::before,
.nav-mobile-toggle span::after {
  content: '';
  position: absolute;
  left: 0;
  width: 100%;
  height: 2px;
  background: var(--color-gray-800);
  transition: all var(--transition-fast);
}
.nav-mobile-toggle span::before { top: -8px; }
.nav-mobile-toggle span::after { top: 8px; }

.nav-mobile-toggle.open span { background: transparent; }
.nav-mobile-toggle.open span::before { top: 0; transform: rotate(45deg); }
.nav-mobile-toggle.open span::after { top: 0; transform: rotate(-45deg); }

.mobile-nav {
  display: none;
  position: fixed;
  top: var(--header-height);
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--color-white);
  overflow-y: auto;
  z-index: 1001;
  transform: translateX(100%);
  transition: transform var(--transition-base);
}
.mobile-nav.open { transform: translateX(0); }

.mobile-nav-inner { padding: 1rem 1.5rem 3rem; }

.mobile-nav-item {
  border-bottom: 1px solid var(--color-gray-100);
}

.mobile-nav-link {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1rem 0;
  font-size: 1rem;
  font-weight: 500;
  color: var(--color-gray-800);
}

.mobile-nav-accordion-btn {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 1rem 0;
  font-size: 1rem;
  font-weight: 500;
  color: var(--color-gray-800);
  text-align: left;
}

.mobile-accordion-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-base);
  background: var(--color-gray-50);
  border-radius: var(--radius-sm);
  margin-bottom: 0.5rem;
}
.mobile-accordion-content.open { max-height: 500px; }

.mobile-sub-label {
  display: block;
  padding: 0.5rem 1rem 0.25rem;
  font-size: 0.6875rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--color-gray-400);
}

.mobile-sub-link {
  display: block;
  padding: 0.625rem 1rem;
  font-size: 0.9375rem;
  color: var(--color-gray-700);
  transition: color var(--transition-fast);
}
.mobile-sub-link:hover { color: var(--color-primary); }

/* ============================================================
   HERO SECTIONS
   ============================================================ */
.hero {
  position: relative;
  min-height: 85vh;
  display: flex;
  align-items: center;
  background: var(--color-navy);
  margin-top: var(--header-height);
  overflow: hidden;
}

.hero-bg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  opacity: 0.55;
}

.hero-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    135deg,
    rgba(0,39,28,0.85) 0%,
    rgba(1,42,45,0.7) 50%,
    rgba(10,22,40,0.6) 100%
  );
}

.hero-content {
  position: relative;
  z-index: 2;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 4rem 1.5rem;
  width: 100%;
}

.hero-label {
  display: inline-block;
  padding: 0.375rem 0.875rem;
  background: rgba(255,255,255,0.15);
  backdrop-filter: blur(8px);
  border: 1px solid rgba(255,255,255,0.2);
  border-radius: 9999px;
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--color-white);
  margin-bottom: 1.5rem;
}

.hero h1 {
  color: var(--color-white);
  max-width: 750px;
  margin-bottom: 1.5rem;
}

.hero-subtitle {
  font-size: 1.125rem;
  line-height: 1.7;
  color: rgba(255,255,255,0.85);
  max-width: 600px;
  margin-bottom: 2rem;
}

.hero-actions { display: flex; gap: 1rem; flex-wrap: wrap; }

/* Hero variants */
.hero-sm { min-height: 50vh; }
.hero-sm .hero-content { padding: 3rem 1.5rem; }
.hero-sm h1 { max-width: 650px; }

/* ============================================================
   SECTIONS
   ============================================================ */
.section {
  padding: 5rem 0;
}

.section-header {
  text-align: center;
  margin-bottom: 3.5rem;
}

.section-header h2 { margin-bottom: 0.75rem; }
.section-header p {
  max-width: 600px;
  margin: 0 auto;
  color: var(--color-gray-500);
  font-size: 1.0625rem;
}

.section-dark {
  background: var(--color-navy);
  color: var(--color-white);
}
.section-dark h2, .section-dark h3 { color: var(--color-white); }
.section-dark p { color: rgba(255,255,255,0.75); }

.section-light { background: var(--color-gray-50); }

/* ============================================================
   CARDS
   ============================================================ */
.card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(340px, 1fr));
  gap: 1.5rem;
}

.card-grid-3 { grid-template-columns: repeat(3, 1fr); }
.card-grid-4 { grid-template-columns: repeat(4, 1fr); }

.card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-100);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: all var(--transition-base);
}
.card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
  border-color: transparent;
}

.card-image {
  width: 100%;
  height: 200px;
  object-fit: cover;
}

.card-body { padding: 1.5rem; }

.card-tag {
  display: inline-block;
  padding: 0.25rem 0.625rem;
  background: var(--color-gray-50);
  border-radius: 9999px;
  font-size: 0.6875rem;
  font-weight: 600;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--color-primary);
  margin-bottom: 0.75rem;
}

.card h3 { font-size: 1.125rem; margin-bottom: 0.5rem; }
.card p { font-size: 0.9375rem; color: var(--color-gray-500); margin-bottom: 1rem; }

.card-footer {
  padding: 1rem 1.5rem;
  border-top: 1px solid var(--color-gray-100);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.card-date {
  font-size: 0.8125rem;
  color: var(--color-gray-400);
}

/* Service Cards */
.service-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-100);
  border-radius: var(--radius-lg);
  padding: 2rem;
  transition: all var(--transition-base);
  display: flex;
  flex-direction: column;
}
.service-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
  border-color: transparent;
}

.service-card-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-md);
  background: var(--color-gray-50);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.25rem;
  font-size: 1.5rem;
  color: var(--color-primary);
  transition: all var(--transition-base);
}
.service-card:hover .service-card-icon {
  background: var(--color-primary);
  color: var(--color-white);
}

.service-card h3 { margin-bottom: 0.5rem; }
.service-card p {
  color: var(--color-gray-500);
  font-size: 0.9375rem;
  flex: 1;
  margin-bottom: 1.25rem;
}

/* Insight Cards */
.insight-card {
  display: flex;
  gap: 1.25rem;
  padding: 1.5rem;
  background: var(--color-white);
  border: 1px solid var(--color-gray-100);
  border-radius: var(--radius-lg);
  transition: all var(--transition-base);
}
.insight-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.insight-card-thumb {
  width: 100px;
  height: 100px;
  border-radius: var(--radius-md);
  object-fit: cover;
  flex-shrink: 0;
}

.insight-card-content h4 {
  font-size: 1rem;
  font-family: var(--font-heading);
  margin-bottom: 0.375rem;
}
.insight-card-content .card-tag { margin-bottom: 0.5rem; }

/* Commitment Cards */
.commitment-card {
  background: var(--color-navy-light);
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: var(--radius-lg);
  padding: 2rem;
  transition: all var(--transition-base);
}
.commitment-card:hover {
  transform: translateY(-4px);
  border-color: rgba(255,255,255,0.2);
  background: rgba(255,255,255,0.05);
}

.commitment-card-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-md);
  background: rgba(200,168,78,0.15);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.25rem;
  color: var(--color-accent);
  font-size: 1.375rem;
}

.commitment-card h3 {
  color: var(--color-white);
  font-size: 1.25rem;
  margin-bottom: 0.625rem;
}
.commitment-card p {
  color: rgba(255,255,255,0.65);
  font-size: 0.9375rem;
  margin-bottom: 1.25rem;
  line-height: 1.7;
}

/* Capability card */
.capability-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-100);
  border-left: 3px solid var(--color-primary);
  border-radius: 0 var(--radius-md) var(--radius-md) 0;
  padding: 1.75rem;
  transition: all var(--transition-base);
}
.capability-card:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-md);
  border-left-color: var(--color-accent);
}

.capability-card h4 {
  font-family: var(--font-heading);
  font-size: 1.125rem;
  margin-bottom: 0.5rem;
  color: var(--color-navy);
}
.capability-card p {
  font-size: 0.9375rem;
  color: var(--color-gray-500);
  line-height: 1.65;
}

/* ============================================================
   ANNOUNCEMENT BANNER
   ============================================================ */
.announcement-banner {
  background: linear-gradient(135deg, var(--color-secondary) 0%, var(--color-secondary-light) 100%);
  padding: 2rem 0;
}

.announcement-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.5rem;
  flex-wrap: wrap;
}

.announcement-text {
  color: var(--color-white);
  font-size: 1.0625rem;
  font-weight: 500;
}

.announcement-dot {
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--color-accent);
  margin-right: 0.75rem;
  animation: pulse-dot 2s ease-in-out infinite;
}

@keyframes pulse-dot {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.5; transform: scale(1.3); }
}

/* ============================================================
   WHAT WE DO — TABBED SECTION
   ============================================================ */
.what-we-do {
  display: grid;
  grid-template-columns: 320px 1fr;
  gap: 3rem;
  align-items: start;
}

.tabs-vertical { display: flex; flex-direction: column; gap: 0.25rem; }

.tab-btn {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 1.125rem 1.25rem;
  text-align: left;
  font-size: 1rem;
  font-weight: 500;
  color: var(--color-gray-600);
  border-left: 3px solid transparent;
  border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
  transition: all var(--transition-fast);
  background: transparent;
}
.tab-btn:hover {
  color: var(--color-primary);
  background: var(--color-gray-50);
}

.tab-btn.active {
  color: var(--color-primary);
  background: var(--color-gray-50);
  border-left-color: var(--color-primary);
  font-weight: 600;
}

.tab-arrow {
  opacity: 0;
  transform: translateX(-8px);
  transition: all var(--transition-fast);
}
.tab-btn.active .tab-arrow { opacity: 1; transform: translateX(0); }

.tab-panel { display: none; }
.tab-panel.active { display: block; }
.tab-panel-inner { animation: fadeSlideIn 400ms ease-out; }

@keyframes fadeSlideIn {
  from { opacity: 0; transform: translateY(12px); }
  to { opacity: 1; transform: translateY(0); }
}

.tab-panel h3 {
  font-size: 1.75rem;
  margin-bottom: 0.75rem;
}

.tab-panel p {
  font-size: 1.0625rem;
  color: var(--color-gray-500);
  line-height: 1.75;
  margin-bottom: 1.5rem;
  max-width: 540px;
}

/* ============================================================
   NEWSLETTER
   ============================================================ */
.newsletter {
  background: var(--color-gray-50);
  padding: 4rem 0;
}

.newsletter-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-100);
  border-radius: var(--radius-lg);
  padding: 3rem;
  text-align: center;
  max-width: 640px;
  margin: 0 auto;
  box-shadow: var(--shadow-sm);
}

.newsletter-card h2 { margin-bottom: 0.5rem; }
.newsletter-card .text-body { margin-bottom: 1.75rem; }

.newsletter-form {
  display: flex;
  gap: 0.75rem;
  max-width: 460px;
  margin: 0 auto;
}

.newsletter-input {
  flex: 1;
  padding: 0.75rem 1rem;
  font-family: var(--font-body);
  font-size: 0.9375rem;
  border: 2px solid var(--color-gray-200);
  border-radius: var(--radius-sm);
  transition: border-color var(--transition-fast);
  outline: none;
}
.newsletter-input:focus { border-color: var(--color-primary); }

/* ============================================================
   PARTNER CAROUSEL (Invest page)
   ============================================================ */
.carousel {
  position: relative;
  overflow: hidden;
}

.carousel-track {
  display: flex;
  transition: transform var(--transition-slow);
}

.carousel-slide {
  min-width: 100%;
  padding: 0 0.5rem;
}

.carousel-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  margin-top: 2rem;
}

.carousel-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 2px solid var(--color-gray-200);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-gray-600);
  transition: all var(--transition-fast);
}
.carousel-btn:hover {
  border-color: var(--color-primary);
  color: var(--color-primary);
  background: var(--color-gray-50);
}

.carousel-dots { display: flex; gap: 0.5rem; }

.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--color-gray-200);
  transition: all var(--transition-fast);
}
.carousel-dot.active {
  background: var(--color-primary);
  width: 28px;
  border-radius: 9999px;
}

/* ============================================================
   TESTIMONIAL
   ============================================================ */
.testimonial {
  padding: 3.5rem 0;
  background: var(--color-gray-50);
}

.testimonial-card {
  max-width: 750px;
  margin: 0 auto;
  text-align: center;
}

.testimonial-quote {
  font-family: var(--font-heading);
  font-size: clamp(1.25rem, 3vw, 1.5rem);
  font-style: italic;
  color: var(--color-navy);
  line-height: 1.6;
  margin-bottom: 1.5rem;
  position: relative;
}
.testimonial-quote::before {
  content: '"';
  font-size: 4rem;
  color: var(--color-accent);
  position: absolute;
  top: -1.5rem;
  left: -1rem;
  font-family: var(--font-heading);
  line-height: 1;
  opacity: 0.4;
}

.testimonial-author {
  font-weight: 600;
  color: var(--color-gray-800);
}
.testimonial-role {
  font-size: 0.875rem;
  color: var(--color-gray-400);
}

/* ============================================================
   FEATURED TOPICS (sidebar)
   ============================================================ */
.featured-topics {
  background: var(--color-gray-50);
  border-radius: var(--radius-lg);
  padding: 1.75rem;
}

.featured-topics h4 {
  font-family: var(--font-body);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--color-gray-400);
  margin-bottom: 1rem;
}

.topic-link {
  display: block;
  padding: 0.75rem 0;
  border-bottom: 1px solid var(--color-gray-100);
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--color-gray-700);
  transition: all var(--transition-fast);
}
.topic-link:last-child { border-bottom: none; }
.topic-link:hover { color: var(--color-primary); padding-left: 0.5rem; }

/* ============================================================
   PAGE HEADER & BREADCRUMB
   ============================================================ */
.page-hero {
  position: relative;
  min-height: 35vh;
  display: flex;
  align-items: center;
  background: var(--color-navy);
  margin-top: var(--header-height);
  overflow: hidden;
}

.page-hero-bg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  opacity: 0.45;
}

.page-hero-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, rgba(0,39,28,0.88) 0%, rgba(1,42,45,0.72) 100%);
}

.page-hero-content {
  position: relative;
  z-index: 2;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 3rem 1.5rem;
  width: 100%;
}

.breadcrumb {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-bottom: 1rem;
  font-size: 0.875rem;
  color: rgba(255,255,255,0.7);
}
.breadcrumb a { color: rgba(255,255,255,0.9); }
.breadcrumb a:hover { color: var(--color-white); text-decoration: underline; }
.breadcrumb-sep { color: rgba(255,255,255,0.4); }

.page-hero-content h1 {
  color: var(--color-white);
  max-width: 650px;
}

/* ============================================================
   STAT BAND
   ============================================================ */
.stat-band {
  padding: 3rem 0;
  background: var(--color-primary);
}

.stat-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
  text-align: center;
}

.stat-number {
  font-family: var(--font-heading);
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--color-accent);
  margin-bottom: 0.25rem;
}

.stat-label {
  font-size: 0.9375rem;
  color: rgba(255,255,255,0.8);
}

/* ============================================================
   PARTNERSHIP HIGHLIGHT
   ============================================================ */
.partner-highlight {
  background: linear-gradient(135deg, var(--color-secondary) 0%, var(--color-navy) 100%);
  padding: 3.5rem 0;
  color: var(--color-white);
}

.partner-highlight-inner {
  max-width: 750px;
  margin: 0 auto;
  text-align: center;
}

.partner-highlight h2 { color: var(--color-white); margin-bottom: 1rem; }
.partner-highlight p {
  color: rgba(255,255,255,0.8);
  font-size: 1.0625rem;
  line-height: 1.75;
}

.partner-stats {
  display: flex;
  justify-content: center;
  gap: 3rem;
  margin-top: 2rem;
}

.partner-stat {
  text-align: center;
}
.partner-stat-number {
  font-family: var(--font-heading);
  font-size: 2.25rem;
  font-weight: 700;
  color: var(--color-accent);
}
.partner-stat-label {
  font-size: 0.875rem;
  color: rgba(255,255,255,0.7);
  margin-top: 0.25rem;
}

/* ============================================================
   RELATED CONTENT
   ============================================================ */
.related-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
}

.related-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-100);
  border-radius: var(--radius-lg);
  padding: 1.5rem;
  transition: all var(--transition-base);
}
.related-card:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-md);
}

.related-card .card-tag { margin-bottom: 0.75rem; }
.related-card h4 {
  font-family: var(--font-heading);
  font-size: 1rem;
  margin-bottom: 0.5rem;
}

/* ============================================================
   DEAL FLOW CTA
   ============================================================ */
.deal-flow-cta {
  background: var(--color-gray-50);
  border: 1px solid var(--color-gray-100);
  border-radius: var(--radius-lg);
  padding: 2.5rem;
  text-align: center;
}

.deal-flow-cta h3 { margin-bottom: 0.75rem; }
.deal-flow-cta p {
  max-width: 500px;
  margin: 0 auto 1.5rem;
  color: var(--color-gray-500);
}

/* ============================================================
   FOOTER
   ============================================================ */
.footer {
  background: var(--color-gray-900);
  color: var(--color-white);
  padding: 4rem 0 0;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 3rem;
  padding-bottom: 3rem;
  border-bottom: 1px solid rgba(255,255,255,0.1);
}

.footer-col h4 {
  font-family: var(--font-body);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: rgba(255,255,255,0.4);
  margin-bottom: 1.25rem;
}

.footer-col p {
  color: rgba(255,255,255,0.55);
  font-size: 0.9375rem;
  line-height: 1.7;
  max-width: 280px;
}

.footer-links { display: flex; flex-direction: column; gap: 0.5rem; }

.footer-links a {
  font-size: 0.9375rem;
  color: rgba(255,255,255,0.55);
  transition: color var(--transition-fast);
}
.footer-links a:hover { color: var(--color-white); }

.footer-bottom {
  padding: 1.5rem 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 1rem;
}

.footer-copyright {
  font-size: 0.8125rem;
  color: rgba(255,255,255,0.35);
}

.footer-legal { display: flex; gap: 1.5rem; flex-wrap: wrap; }
.footer-legal a {
  font-size: 0.8125rem;
  color: rgba(255,255,255,0.4);
  transition: color var(--transition-fast);
}
.footer-legal a:hover { color: rgba(255,255,255,0.7); }

/* ============================================================
   MODAL
   ============================================================ */
.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.6);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 2000;
  opacity: 0;
  visibility: hidden;
  transition: all var(--transition-base);
}
.modal-overlay.open { opacity: 1; visibility: visible; }

.modal {
  background: var(--color-white);
  border-radius: var(--radius-lg);
  padding: 2.5rem;
  max-width: 480px;
  width: 90%;
  box-shadow: var(--shadow-xl);
  text-align: center;
  transform: translateY(20px);
  transition: transform var(--transition-base);
}
.modal-overlay.open .modal { transform: translateY(0); }

.modal-close {
  position: absolute;
  top: 1rem;
  right: 1rem;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  color: var(--color-gray-400);
  transition: all var(--transition-fast);
}
.modal-close:hover { background: var(--color-gray-50); color: var(--color-gray-800); }

.modal h3 { margin-bottom: 0.5rem; }
.modal p { color: var(--color-gray-500); margin-bottom: 1.5rem; font-size: 0.9375rem; }

.modal .newsletter-form { max-width: 100%; }

.modal-success {
  display: none;
  padding: 1.5rem;
}
.modal-success.show { display: block; }
.modal-success-icon {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--color-primary);
  color: var(--color-white);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.75rem;
  margin: 0 auto 1rem;
}

/* ============================================================
   RESPONSIVE
   ============================================================ */
@media (max-width: 1024px) {
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .card-grid-3 { grid-template-columns: repeat(2, 1fr); }
  .card-grid-4 { grid-template-columns: repeat(2, 1fr); }
  .related-grid { grid-template-columns: repeat(2, 1fr); }
  .what-we-do { grid-template-columns: 250px 1fr; gap: 2rem; }
  .mega-menu-inner { gap: 2rem; }
}

@media (max-width: 768px) {
  .nav-desktop { display: none; }
  .nav-mobile-toggle { display: flex; }
  .mobile-nav { display: block; }

  .section { padding: 3rem 0; }
  .hero { min-height: 70vh; }
  .hero h1 { font-size: 2rem; }

  .what-we-do { grid-template-columns: 1fr; gap: 1.5rem; }
  .tabs-vertical {
    flex-direction: row;
    overflow-x: auto;
    gap: 0.25rem;
    padding-bottom: 0.5rem;
  }
  .tab-btn {
    border-left: none;
    border-bottom: 3px solid transparent;
    border-radius: var(--radius-sm) var(--radius-sm) 0 0;
    padding: 0.75rem 1rem;
    white-space: nowrap;
    flex-shrink: 0;
    font-size: 0.875rem;
  }
  .tab-btn.active {
    border-left-color: transparent;
    border-bottom-color: var(--color-primary);
  }
  .tab-arrow { display: none; }

  .mega-menu-inner { grid-template-columns: 1fr; gap: 1.5rem; }
  .card-grid { grid-template-columns: 1fr; }
  .card-grid-3 { grid-template-columns: 1fr; }
  .card-grid-4 { grid-template-columns: 1fr; }
  .related-grid { grid-template-columns: 1fr; }
  .stat-grid { grid-template-columns: 1fr; gap: 1.5rem; }
  .footer-grid { grid-template-columns: 1fr; gap: 2rem; }
  .partner-stats { flex-direction: column; gap: 1.5rem; }
  .insight-card { flex-direction: column; }
  .insight-card-thumb { width: 100%; height: 160px; }
  .announcement-inner { flex-direction: column; text-align: center; }
  .newsletter-form { flex-direction: column; }
  .newsletter-card { padding: 2rem 1.5rem; }
  .hero-actions { flex-direction: column; }
}

@media (max-width: 480px) {
  .container { padding: 0 1rem; }
  .section-header h2 { font-size: 1.5rem; }
  .btn { padding: 0.625rem 1.25rem; font-size: 0.875rem; }
}

